/*
 * test_trigger.c - driver for the product trigger module (ticket T-trigT).
 *
 * Written from the SPEC (docs/agent/hadi/briefs/T-trig_spec.md). It performs the directed ops of
 * build/scripts.h (generated by oracle.py), then NEP random episodes (xorshift32, mirrored in
 * oracle.py: the order of the rnd() calls must stay identical), and prints one short line per op
 * (simavr splits UART lines longer than 255 characters):
 *   S n | M mg counts | N case ret unchanged |
 *   <tag> ret state stat run quiet warm seeded b0 b1 b2 thr lo thr_mg debounce quiet_cfg warm_cfg statistic()
 * with tag I(nit) T(hreshold) F(eed) R(elease) Y(resync). run_tests.py compares every line with oracle.py.
 *
 * Host: test_trigger SEED NEP.  AVR: -DTEST_SEED=<n>u -DTEST_NEP=<n>u.
 * WORKING ASSUMPTION: open_questions Q2, Q3, not decided.
 */
#include <stdint.h>
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <stdbool.h>
#include <stddef.h>
#include "trigger.h"
#include "sim16.h"
#include "scripts.h"

#define OP_INITNULL 1
#define OP_INIT 2
#define OP_SETTHR 3
#define OP_FEED 4
#define OP_RELEASE 5
#define OP_RESYNC 6
#define OP_MG2C 7
#define OP_SCEN 8
#define OP_NULLS 9

#define NSAMP 300u

static trigger_t T;

/**
 * Map the module's state value onto the order WARMUP=0, ARMED=1, LOCKED=2, REARM=3.
 *
 * @param s value of trigger_t.state.
 * @return 0..3, or 9 for an unknown value.
 */
static int16_t state_no(uint8_t s)
{
    if (s == (uint8_t)TRIG_WARMUP) { return 0; }
    if (s == (uint8_t)TRIG_ARMED) { return 1; }
    if (s == (uint8_t)TRIG_LOCKED) { return 2; }
    if (s == (uint8_t)TRIG_REARM) { return 3; }
    return 9;
}

/**
 * Print the uniform state line of the global trigger T.
 *
 * @param tag line tag character.
 * @param ret return value to show (1 when trigger_feed fired).
 * @return None.
 */
static void snap(char tag, int16_t ret)
{
    printf("%c %d %d %u %u %u %u %u %ld %ld %ld %u %u %u %u %u %u %u\n", tag, (int)ret,
           (int)state_no((uint8_t)T.state), (unsigned)T.stat, (unsigned)T.run, (unsigned)T.quiet_n,
           (unsigned)T.warm_n, (unsigned)T.seeded, (long)T.base[0], (long)T.base[1], (long)T.base[2],
           (unsigned)T.thr, (unsigned)T.lo, (unsigned)T.thr_mg, (unsigned)T.cfg.debounce,
           (unsigned)T.cfg.quiet, (unsigned)T.cfg.warm, (unsigned)trigger_statistic(&T));
}

/**
 * Exercise every function with NULL pointers; each must return 0/false and leave T untouched.
 * Prints "N case ret unchanged" for the 8 cases.
 *
 * @return None.
 */
static void null_tests(void)
{
    trigger_t before;
    const int16_t s[3] = {100, -100, 50};
    trigger_cfg_t cfg = {1u, 16u, 16u};
    bool r;
    uint16_t u;

    memcpy(&before, &T, sizeof T);
    r = trigger_feed(NULL, s);
    printf("N 1 %d %d\n", (int)r, memcmp(&before, &T, sizeof T) == 0);
    r = trigger_feed(&T, NULL);
    printf("N 2 %d %d\n", (int)r, memcmp(&before, &T, sizeof T) == 0);
    u = trigger_statistic(NULL);
    printf("N 3 %u %d\n", (unsigned)u, memcmp(&before, &T, sizeof T) == 0);
    trigger_init(NULL, &cfg);
    printf("N 4 0 %d\n", memcmp(&before, &T, sizeof T) == 0);
    trigger_set_threshold_mg(NULL, 500u);
    printf("N 5 0 %d\n", memcmp(&before, &T, sizeof T) == 0);
    trigger_release(NULL);
    printf("N 6 0 %d\n", memcmp(&before, &T, sizeof T) == 0);
    trigger_resync(NULL);
    printf("N 7 0 %d\n", memcmp(&before, &T, sizeof T) == 0);
    trigger_init(NULL, NULL);
    printf("N 8 0 %d\n", memcmp(&before, &T, sizeof T) == 0);
}

/**
 * Execute one op.
 *
 * @param op op code (OP_*).
 * @param a first operand (mg for threshold ops, x for feed, debounce for init, scenario number for scen).
 * @param b second operand (y, quiet).
 * @param c third operand (z, warm).
 * @return 1 if the op was a feed that fired, else 0.
 */
static int16_t do_op(int16_t op, int16_t a, int16_t b, int16_t c)
{
    int16_t s[3];
    trigger_cfg_t cfg;
    bool r;
    uint16_t mg;

    switch (op) {
    case OP_INITNULL:
        trigger_init(&T, NULL);
        snap('I', 0);
        break;
    case OP_INIT:
        cfg.debounce = (uint8_t)a; cfg.quiet = (uint8_t)b; cfg.warm = (uint8_t)c;
        trigger_init(&T, &cfg);
        snap('I', 0);
        break;
    case OP_SETTHR:
        trigger_set_threshold_mg(&T, (uint16_t)a);
        snap('T', 0);
        break;
    case OP_FEED:
        s[0] = a; s[1] = b; s[2] = c;
        r = trigger_feed(&T, s);
        snap('F', r ? 1 : 0);
        return r ? 1 : 0;
    case OP_RELEASE:
        trigger_release(&T);
        snap('R', 0);
        break;
    case OP_RESYNC:
        trigger_resync(&T);
        snap('Y', 0);
        break;
    case OP_MG2C:
        mg = (uint16_t)a;
        printf("M %u %u\n", (unsigned)mg, (unsigned)trigger_mg_to_counts(mg));
        break;
    case OP_SCEN:
        printf("S %d\n", (int)a);
        break;
    case OP_NULLS:
        null_tests();
        break;
    default:
        printf("BAD OP %d\n", (int)op);
        break;
    }
    return 0;
}

/* ---- random episodes (mirror of episode() in oracle.py) ---- */
static uint32_t rs;

/**
 * xorshift32 step reduced modulo n.
 *
 * @param n modulus (> 0).
 * @return pseudo-random value in [0, n).
 */
static uint32_t rnd(uint32_t n)
{
    rs ^= rs << 13;
    rs ^= rs >> 17;
    rs ^= rs << 5;
    return rs % n;
}

static const uint8_t DBS[6] = {0, 1, 2, 3, 4, 7};
static const uint8_t QQ[7] = {0, 15, 16, 17, 30, 40, 255};
static const uint8_t WW[6] = {0, 15, 16, 20, 32, 50};
static const uint16_t MGS[10] = {0, 1, 2, 100, 250, 500, 1000, 3000, 24567, 65535};
static const int16_t AMPS[4] = {3, 40, 300, 1200};

/**
 * Draw a threshold in mg: one time in six a random value below 5000, else one of the table values.
 *
 * @return threshold in mg.
 */
static uint16_t pick_mg(void)
{
    uint32_t v = rnd(6u);
    uint32_t i;
    if (v == 0u) {
        return (uint16_t)rnd(5000u);
    }
    i = rnd(10u);
    return MGS[i];
}

/**
 * Run random episode k on the global trigger.
 *
 * @param seed base seed.
 * @param k episode number.
 * @param nsamp number of samples to feed.
 * @return None.
 */
static void episode(uint32_t seed, uint32_t k, uint16_t nsamp)
{
    uint32_t u, v, d, q, w;
    int32_t o[3];
    int32_t val;
    int16_t s[3];
    int16_t phase = 0, plen = 0, rel_in = 0, amp, ret;
    uint16_t n, mg;
    uint8_t j;

    rs = seed * 2654435761u + k * 40503u + 12345u;
    if (rs == 0u) { rs = 1u; }
    do_op(OP_SCEN, (int16_t)(1000u + k), 0, 0);
    u = rnd(8u);
    if (u == 0u) {
        do_op(OP_INITNULL, 0, 0, 0);
    } else {
        d = DBS[rnd(6u)];
        q = QQ[rnd(7u)];
        w = WW[rnd(6u)];
        do_op(OP_INIT, (int16_t)d, (int16_t)q, (int16_t)w);
    }
    mg = pick_mg();
    do_op(OP_SETTHR, (int16_t)mg, 0, 0);
    for (j = 0u; j < 3u; j++) {
        o[j] = (int32_t)rnd(3001u) - 1500;
    }
    for (n = 0u; n < nsamp; n++) {
        u = rnd(64u);
        if (u == 0u) {
            do_op(OP_RESYNC, 0, 0, 0);
        } else if (u <= 2u) {
            mg = pick_mg();
            do_op(OP_SETTHR, (int16_t)mg, 0, 0);
        }
        if (plen == 0) {
            phase = (int16_t)rnd(5u);
            plen = (int16_t)(8u + rnd(50u));
            v = rnd(4u);
            if (v == 0u) {
                for (j = 0u; j < 3u; j++) {
                    o[j] = (int32_t)rnd(3001u) - 1500;
                }
            }
        }
        plen--;
        for (j = 0u; j < 3u; j++) {
            if (phase == 4) {
                v = rnd(6u);
                switch (v) {
                case 0u: val = -32768L; break;
                case 1u: val = 32767L; break;
                case 2u: val = -2048L; break;
                case 3u: val = 2047L; break;
                case 4u: val = 0L; break;
                default: val = o[j]; break;
                }
            } else {
                amp = AMPS[phase];
                val = o[j] + (int32_t)rnd((uint32_t)(2 * amp + 1)) - amp;
            }
            if (val < -32768L) { val = -32768L; }
            if (val > 32767L) { val = 32767L; }
            s[j] = (int16_t)val;
        }
        ret = do_op(OP_FEED, s[0], s[1], s[2]);
        if (ret != 0) {
            rel_in = (int16_t)(3u + rnd(30u));
        } else if (rel_in > 0) {
            rel_in--;
            if (rel_in == 0) {
                do_op(OP_RELEASE, 0, 0, 0);
            }
        }
        v = rnd(24u);
        if (v == 0u) {
            do_op(OP_RELEASE, 0, 0, 0);
        }
    }
}

